import java.util.*;
import java.io.*;

public class Main {
    static final long INF = (long)1e15;
    static final int MAX_LIMIT = 1000010;
    static List<Long> seq = new ArrayList<>();
    static int minStepsFound = MAX_LIMIT;

    public static void explore(long x, int steps) {
        if (steps > minStepsFound)
            return;
        if (x == 0) {
            minStepsFound = steps;
            return;
        }
        int startIdx = Collections.binarySearch(seq, x);
        if (startIdx < 0) {
            startIdx = -startIdx - 1;
        }
        int endIdx = Collections.binarySearch(seq, x);
        if (endIdx < 0) {
            endIdx = -endIdx - 1;
        } else {
            endIdx = startIdx;
        }
        if (startIdx == endIdx) {
            startIdx--;
        }
        long startVal = seq.get(startIdx);
        long diff1 = x - startVal;
        int cost = startIdx;
        long endVal = seq.get(endIdx);
        long diff2 = endVal - x;
        explore(x % startVal, steps + cost * (x / startVal));
        explore(diff2, steps + cost + 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        seq.add(0L);
        for (int i = 1; i <= 16; ++i) {
            long last = seq.get(seq.size() - 1);
            seq.add(last * 10 + 1);
        }
        explore(n, 0);
        System.out.println(minStepsFound);
    }
}
